import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        long[] y = new long[n];
        for (int i = 0; i < n; i++) y[i] = nextLong() - i;  // the target becomes sum |y[i] - k|
        Arrays.sort(y);
        long med = y[n / 2], sum = 0;
        for (long v : y) sum += Math.abs(v - med);
        System.out.println(sum);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	y := make([]int64, n)
	for i := range y {
		y[i] = nextInt() - int64(i) // the target becomes sum |y[i] - k|
	}
	slices.Sort(y)
	med := y[n/2]
	var sum int64
	for _, v := range y {
		if v > med {
			sum += v - med
		} else {
			sum += med - v
		}
	}
	fmt.Println(sum)
}
